package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class,qualifiers="w360dp-h800dp-mdpi",shadows={ReferenceDesign5150Test.LocalStorage.class}) @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class Study5160Test {
 ReferenceDesign5150Test f;MainActivity a;StudyHub h;long course,subject,other;long now;
 @Before public void before()throws Exception{f=new ReferenceDesign5150Test();f.before();a=f.a;h=a.studies;now=System.currentTimeMillis();course=h.db.save("courses",0,StudyStore.values("title","Curso de ensaio","description","","created",now));subject=h.db.save("subjects",0,StudyStore.values("title","Biologia","course",course,"color",a.accent,"created",now));other=h.db.save("subjects",0,StudyStore.values("title","Outra disciplina","color",a.accent,"created",now));a.tab="Estudos";h.course=course;h.subject=subject;h.section="Visão geral";a.render();drain();}
 @After public void after()throws Exception{f.after();}
 void drain()throws Exception{f.drain();for(int i=0;i<3;i++){h.worker.submit(()->{}).get(15,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();}}
 long card(String text,long group,long due){return h.db.save("cards",0,StudyStore.values("subject",group,"front",text,"back","Resposta de "+text,"due",due,"updated",now));}
 List<Long> cards(int n){List<Long> ids=new ArrayList<>();for(int i=0;i<n;i++)ids.add(card("Pergunta "+i,subject,now-1000));return ids;}
 UiDialog dialog(){return (UiDialog)ShadowDialog.getLatestDialog();}
 View text(View v,String label){return VoiceToolsTest.findText(v,label);}
 void click(String label){View v=text(dialog().root,label);assertNotNull(label,v);assertTrue(label,v.performClick());}
 JSONObject state(){return StudyReview.saved(h.prefs);}
 @Test public void todayAggregatesAllSessionsAndHonoursTheSelectedDiscipline()throws Exception{long current=System.currentTimeMillis();android.database.sqlite.SQLiteDatabase db=h.db.getWritableDatabase();db.beginTransaction();try{for(int i=0;i<1100;i++)db.execSQL("INSERT INTO sessions(subject,started,seconds,goal,type,token) VALUES(?,?,?,?,?,?)",new Object[]{subject,current,60,"Foco","Foco","today-"+i});db.execSQL("INSERT INTO sessions(subject,started,seconds,goal,type,token) VALUES(?,?,?,?,?,?)",new Object[]{other,current,9999,"Foco","Foco","other"});db.setTransactionSuccessful();}finally{db.endTransaction();}card("Devido",subject,current-1);card("Futuro",subject,current+86400000);long paused=card("Pausado",subject,current-1);h.db.save("cards",paused,StudyStore.values("suspended",1));card("Outro",other,current-1);StudyToday.Snapshot s=StudyToday.load(h.db,course,subject,current);assertEquals(1100*60,s.focus);assertEquals(1,s.due);assertEquals(0,s.reviewed);}
 @Test public void dailyReviewCounterCountsCardsRatherThanRepeatedAnswers()throws Exception{long id=card("Uma pergunta",subject,now-1);h.db.grade(id,0,"review-a");h.db.grade(id,2,"review-b");assertEquals(1,StudyToday.load(h.db,course,subject,System.currentTimeMillis()).reviewed);assertEquals(0,StudyToday.load(h.db,0,other,System.currentTimeMillis()).reviewed);}
 @Test public void continueStudyingPreservesTheExistingReaderLocation()throws Exception{long id=h.db.save("materials",0,StudyStore.values("subject",subject,"title","Livro de Biologia","name","Biologia.pdf","mime","application/pdf","path","/private/book.pdf","hash",String.join("",Collections.nCopies(64,"a")),"bytes",100,"progress",37,"status","A estudar","created",now,"updated",now));h.reload();drain();View button=text(h.content,"Continuar a estudar");assertNotNull(button);View clickable=button;while(!clickable.isClickable()&&clickable.getParent() instanceof View)clickable=(View)clickable.getParent();clickable.performClick();Intent intent=shadowOf(a).getNextStartedActivity();assertNotNull(intent);assertEquals(id,intent.getLongExtra("study_material",0));assertFalse(intent.hasExtra("study_segment"));}
 @Test public void priorityTasksExcludeDoneFutureUndatedAndOtherSubjects()throws Exception{for(int i=0;i<5;i++)h.db.save("tasks",0,StudyStore.values("subject",i==4?other:subject,"title","Tarefa "+i,"due",i==0?now-2*86400000L:i==1?0:i==2?now+2*86400000L:now-100,"done",i==3?1:0,"updated",now));StudyToday.Snapshot s=StudyToday.load(h.db,course,subject,now);assertEquals(1,s.overdue);assertEquals(1,s.tasks.size());assertEquals("Tarefa 0",s.tasks.get(0).s("title"));}
 @Test public void reviewLimitsTheQueueAndExcludesFutureSuspendedAndOtherCards()throws Exception{cards(15);long paused=card("Pausado",subject,now-1);h.db.save("cards",paused,StudyStore.values("suspended",1));card("Futuro",subject,now+100000);card("Outro",other,now-1);new StudyReview(h).start(10);drain();assertEquals(10,state().getJSONArray("queue").length());assertEquals(subject,state().getLong("subject"));assertFalse(StudyReview.pendingFor(h.prefs,0,other));assertTrue(StudyReview.pendingFor(h.prefs,course,0));}
 @Test public void answerIsHiddenAndDoubleTappingGradesOnlyOnce()throws Exception{cards(3);new StudyReview(h).start(10);drain();View answer=text(dialog().root,"Resposta de Pergunta 0");assertNotNull(answer);assertEquals(View.GONE,answer.getVisibility());click("Mostrar resposta");assertEquals(View.VISIBLE,answer.getVisibility());View grade=text(dialog().root,"Recordei · 1 dia");assertNotNull(grade);grade.performClick();grade.performClick();drain();assertEquals(1,h.db.count("reviews",null,null));assertEquals(1,state().getInt("at"));assertEquals(1,state().getJSONArray("grades").getInt(2));dialog().getButton(-2).performClick();new StudyReview(h).resume();drain();assertNotNull(text(dialog().root,"Pergunta 1"));assertEquals(1,h.db.count("reviews",null,null));}
 @Test public void interruptedGradeIsRecoveredWithoutReschedulingItTwice()throws Exception{List<Long> ids=cards(2);new StudyReview(h).start(10);drain();JSONObject s=state();h.db.grade(ids.get(0),2,s.getString("token")+":0");long due=h.db.get("cards",ids.get(0)).n("due");dialog().dismiss();new StudyReview(h).resume();drain();assertEquals(1,state().getInt("at"));assertEquals(1,state().getJSONArray("grades").getInt(2));assertEquals(due,h.db.get("cards",ids.get(0)).n("due"));assertEquals(1,h.db.count("reviews",null,null));assertNotNull(text(dialog().root,"Pergunta 1"));}
 @Test public void resumeSkipsDeletedEditedAndSuspendedCards()throws Exception{List<Long> ids=cards(4);new StudyReview(h).start(10);drain();dialog().dismiss();h.db.delete("cards",ids.get(0));h.db.save("cards",ids.get(1),StudyStore.values("front","Texto alterado","updated",now+1));h.db.save("cards",ids.get(2),StudyStore.values("suspended",1));new StudyReview(h).resume();drain();assertEquals(3,state().getInt("at"));assertEquals(3,state().getInt("skipped"));assertNotNull(text(dialog().root,"Pergunta 3"));assertEquals(0,h.db.count("reviews",null,null));}
 @Test public void completedReviewShowsHonestTotalsAndActualNextIntervals()throws Exception{List<Long> ids=cards(1);h.reload();drain();assertEquals(1,h.today.due);new StudyReview(h).start(10);drain();click("Mostrar resposta");click("Fácil · 4 dias");drain();assertFalse(StudyReview.pending(h.prefs));assertTrue(BooksToolsTest.labels(dialog().root).contains("Fácil: 1"));assertEquals(4,h.db.get("cards",ids.get(0)).n("interval"));assertEquals(0,h.today.due);}
 @Test public void reviewCanOpenTheExactSourcePartWithoutLosingTheQueue()throws Exception{long material=h.db.save("materials",0,StudyStore.values("subject",subject,"title","Fonte","name","Fonte.pdf","mime","application/pdf","path","/private/source.pdf","hash",String.join("",Collections.nCopies(64,"b")),"bytes",100,"created",now,"updated",now));long id=card("Com fonte",subject,now-1);h.db.save("cards",id,StudyStore.values("material",material,"segment",7));new StudyReview(h).start(10);drain();click("Ver material de origem");drain();Intent intent=shadowOf(a).getNextStartedActivity();assertEquals(7,intent.getIntExtra("study_segment",-1));assertTrue(StudyReview.pending(h.prefs));assertEquals(0,state().getInt("at"));}
 @Test public void todayAndReviewHaveNativePreviews()throws Exception{cards(3);h.db.save("tasks",0,StudyStore.values("subject",subject,"title","Rever a estrutura da célula","due",now,"estimate",20,"updated",now));h.reload();drain();f.capture(a.shell,"estudos-hoje-5160",360,800);new StudyReview(h).start(10);drain();click("Mostrar resposta");f.capture(dialog().root,"revisao-5160",336,610);}
 @Test public void completingAnOpenQuestionDoesNotResurrectItsDelayedDraft()throws Exception{long id=h.db.save("questions",0,StudyStore.values("subject",subject,"prompt","Explique a ideia","answer","Uma resposta de referência","kind",0,"updated",now));StudyHub.Quiz quiz=h.new Quiz(Collections.singletonList(h.db.get("questions",id)),subject);quiz.persist();drain();quiz.show();EditText input=findEdit(dialog().root);assertNotNull(input);input.setText("A minha explicação.");click("Comparar com a referência");dialog().getButton(-1).performClick();dialog().getButton(-1).performClick();drain();shadowOf(Looper.getMainLooper()).idleFor(2,TimeUnit.SECONDS);drain();assertEquals(0,h.db.count("practice",null,null));assertEquals(1,h.db.count("quiz_runs",null,null));}
 @Test public void completingAPriorityTaskUpdatesThePlanAndKeepsOtherTasks()throws Exception{long id=h.db.save("tasks",0,StudyStore.values("subject",subject,"title","Tarefa de hoje","due",now,"updated",now));long second=h.db.save("tasks",0,StudyStore.values("subject",other,"title","Outra tarefa","due",now,"updated",now));h.reload();drain();View finish=text(h.content,"Concluir");assertNotNull(finish);finish.performClick();drain();assertEquals(1,h.db.get("tasks",id).n("done"));assertEquals(0,h.db.get("tasks",second).n("done"));assertEquals(0,h.today.tasks.size());}
 @Test public void inconsistentSavedReviewIsRejectedWithoutChangingAnyCards()throws Exception{cards(1);new StudyReview(h).start(10);drain();JSONObject bad=state();bad.getJSONArray("grades").put(2,9);h.prefs.edit().putString(StudyReview.KEY,bad.toString()).commit();assertNull(StudyReview.saved(h.prefs));assertFalse(StudyReview.pendingFor(h.prefs,course,subject));assertEquals(1,h.db.count("cards",null,null));assertEquals(0,h.db.count("reviews",null,null));}
 @Test public void todayShowsControlsForTheActiveFocusInsteadOfStartingAnother()throws Exception{h.prefs.edit().putBoolean("timer_active",true).putBoolean("timer_paused",true).putLong("timer_acc",20).putLong("timer_limit",1500).putString("timer_goal","Compreender a matéria").apply();h.draw();assertNotNull(text(h.content,"Continuar foco"));assertNull(text(h.content,"Iniciar foco"));h.prefs.edit().putBoolean("timer_active",false).apply();}
 EditText findEdit(View v){if(v instanceof EditText)return (EditText)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){EditText x=findEdit(g.getChildAt(i));if(x!=null)return x;}}return null;}
}
